import type { ComponentType } from "react"

/** What a registry entry renders. Mirrors the `kind` segment of a `/view` URL. */
export type RegistryKind = "component" | "example" | "screen"

/** One file a registry item distributes. The shape `/r/<name>.json` serves. */
export interface RegistrySourceFile {
  path: string
  type: string
  target?: string
  /**
   * The file's own text. Mandatory in practice: shadcn's installer skips any
   * entry without one, silently, and still reports the install as a success.
   */
  content?: string
}

export interface RegistryEntry {
  /** The catalogue id, or an example name such as `range-bar-status`. */
  name: string
  /** Behaviour variant. `base` is the only one; the folder proves the axis exists. */
  base: string
  /** CSS-only variant. `base-lyra` is the default. */
  style: string
  kind: RegistryKind
  /**
   * Lazily loaded renderable. The type is `| null` because the field is part of
   * the shape a consumer checks, not because a generated entry ever carries one:
   * an entry exists only where a file does.
   */
  component: (() => Promise<{ default: ComponentType<Record<string, unknown>> }>) | null
  /** The real source text, for `<ComponentSource>`. */
  source: string | null
  /**
   * A pre-built registry-item.json payload. Always `null`: the item served at
   * `/r/<name>.json` is assembled from the catalogue row and `files` by
   * `app/_machine/registry-payload.ts`, so a second copy here would be a second
   * thing to keep in step.
   */
  meta: Record<string, unknown> | null
  /**
   * The files this item distributes, own file first and the shared substrate
   * after it. The machine routes read this directly to build a registry-item
   * response, so what is here is what `shadcn add` writes to disk.
   */
  files?: RegistrySourceFile[]
}

/** Behaviour variants. A second base is a folder under `registry/bases/`, never a URL migration. */
export const REGISTRY_BASES: string[] = ["base"]

/** Style variants. Style is a stylesheet and nothing else; see decision 6. */
export const REGISTRY_STYLES: string[] = ["base-lyra"]

const SOURCE_BASES_BASE_STATUS_PILL = "/**\n * THROWAWAY — pipeline proof only (brief §0.6). Replaced in Phase 2.\n *\n * It exists to answer four questions before anything is designed:\n * does `findBuilt()` see a flat file here, does `REGISTRY_INDEX` gain exactly\n * one entry, does `/view/base/base-lyra/component/status-pill` render with\n * `data-opsin-view-state=\"ready\"`, and does the emitted\n * `ComponentType<Record<string, unknown>>` typing accept a zero-prop default\n * export. Nothing here is the specification.\n */\n\nexport interface StatusPillProps {\n  /** Placeholder. The real interface arrives in Phase 2. */\n  label: string\n}\n\nexport function StatusPill({ label }: StatusPillProps) {\n  return <span data-slot=\"status-pill\">{label}</span>\n}\n\nexport default function StatusPillDemo() {\n  return <StatusPill label=\"Pipeline proof\" />\n}\n"

const SHARED_LIB_OPSINJS_TS = "/**\n * lib/opsinjs.ts — the shared substrate every opsinjs component imports.\n *\n * WHY THIS FILE EXISTS\n * A component under `registry/bases/<base>/` is distributed by `shadcn add`,\n * which copies source files into somebody else's project. Anything a component\n * imports has to travel with it or the copy will not compile, and a component\n * that compiles here and breaks there is worse than no component at all. So the\n * import surface of a registry file is exactly two modules: `@/lib/utils` for\n * `cn`, which `shadcn init` writes into every consumer, and this one, which\n * `scripts/build-registry.mts` appends to every component's `files[]` as a\n * `registry:lib` entry carrying real `content`. There is no third. Not\n * `@/components/*`, not `@/registry/*`, not `@/app/*`, not `@/tokens/*` — those\n * paths exist in this repository and nowhere else.\n *\n * `type: \"registry:lib\"` resolves through the consumer's `components.json`\n * `aliases.lib`, and shadcn 4.20 rewrites a `@/lib/...` import specifier to the\n * same alias, so `@/lib/opsinjs` names the same file in this repository and in a\n * project that installed from it. Nothing is rewritten by hand at either end.\n *\n * IT RE-EXPORTS AND IT NEVER RE-DECLARES. The clinical vocabulary lives in\n * `lib/status.ts`, which is the module the documentation chrome, the section\n * contracts and `assert-ia.mts` already read. A second copy of `CLINICAL_STATUSES`\n * here would be a second copy that can drift, and the two axes are the one thing\n * in this system that must never say two different things. `lib/status.ts` ships\n * beside this file for the same reason, as a second `registry:lib` entry.\n *\n * WHAT IS DECLARED HERE, AND WHY IT IS HERE RATHER THAN IN A COMPONENT\n * Only the shapes that more than one component has to agree on: a reference\n * range, a point on a trend, a sheet detent, a material rung, and the one string\n * every example is allowed to cite as its source. A shape used by exactly one\n * component belongs in that component's own file, because a type nobody else\n * consumes is not substrate, it is that component's API.\n *\n * CONSTRAINTS THIS FILE IS UNDER\n * No JSX and no non-erasable TypeScript — no `enum`, no parameter properties, no\n * `namespace` — and every relative import carries an explicit `.ts` extension,\n * because `scripts/*.mts` run under plain Node 24 with native type stripping and\n * some of them import `lib/` modules directly, with no resolver hook. The same\n * rule holds for `lib/status.ts`, `lib/catalogue.ts`, `lib/routes.ts` and\n * `registry/catalogue.ts`.\n *\n * `scripts/build-reference.mts` scans `lib/` and turns every exported type and\n * interface into a page under `content/docs/reference/api/`, taking the first\n * sentence of the doc comment directly above the declaration as the summary. The\n * comments below are therefore published documentation, not notes to the next\n * reader of the source.\n *\n * NOT YET HERE. `warnOnce()` and the `OPSIN_ERRORS` channel — the runtime that\n * reports OPSIN-0001 (both colour axes on one surface) and OPSIN-0004 (a range\n * with no source) — belong in this file and are owned by a later batch. Leave\n * room for them; do not add a second error module elsewhere when they arrive.\n */\n\nimport type { ClinicalStatus } from \"./status\"\n\n/* ------------------------------------------------------------------ *\n * The clinical vocabulary, re-exported from lib/status.ts             *\n *                                                                     *\n * A component imports these from `@/lib/opsinjs` and never from       *\n * `@/lib/status` directly. Both files ship, so either specifier would  *\n * resolve in a consumer — but one import surface is what makes the     *\n * substrate reviewable, and it is the specifier every specification    *\n * page's `## Usage` block prints.                                      *\n * ------------------------------------------------------------------ */\n\nexport {\n  CLINICAL_STATUSES,\n  CLINICAL_STATUS_META,\n  HEALTH_CATEGORIES,\n  HEALTH_CATEGORY_LABELS,\n  isClinicalStatus,\n  isHealthCategory,\n  axisConflict,\n} from \"./status\"\n\nexport type {\n  ClinicalStatus,\n  UnknownStatus,\n  ClinicalStatusOrUnknown,\n  ClinicalStatusMeta,\n  HealthCategory,\n  AxisConflict,\n} from \"./status\"\n\n/* ------------------------------------------------------------------ *\n * Example data                                                        *\n * ------------------------------------------------------------------ */\n\n/**\n * The only citation an opsinjs example, demo or preview may carry.\n *\n * Every component ships a zero-prop default export that renders in the docs and\n * in a consumer's editor, and every one of those renders a measurement. A\n * plausible reference range in a demo is a reference range somebody will read as\n * theirs, so the demos cite this string instead — one literal, shared by all of\n * them, saying in the reader's own language that the numbers beside it mean\n * nothing. `ReferenceRange.source` in an example is always this and never a\n * laboratory, a guideline body, a device manufacturer or a study.\n */\nexport const EXAMPLE_SOURCE = \"Example data — not a reference range\"\n\n/* ------------------------------------------------------------------ *\n * Shapes more than one component agrees on                            *\n * ------------------------------------------------------------------ */\n\n/**\n * The interval a reading is being compared against, and who says so.\n *\n * Both bounds are optional because a one-sided range is a real range: some\n * measurements have a floor and no ceiling, and rendering a bound the product\n * did not supply would invent a threshold. An omitted bound renders as an open\n * end, never as zero and never as an assumed limit.\n *\n * `source` is required, and it is required because opsinjs does not own a single\n * clinical number. A range arriving with no attribution is the consuming\n * product asking this system to vouch for a threshold it has never seen, which\n * is the one thing it must not do; a component handed a range with no `source`\n * reports OPSIN-0004 rather than drawing it.\n */\nexport interface ReferenceRange {\n  /** Lower bound, in the reading's own unit. Omitted means the range is open below. */\n  low?: number\n  /** Upper bound, in the reading's own unit. Omitted means the range is open above. */\n  high?: number\n  /** Who this interval came from. Never opsinjs, and never omitted. */\n  source: string\n  /**\n   * When the range was published or last reviewed, ISO 8601. Omitted when the\n   * product does not know — which is rendered as \"we do not know\", never as\n   * today's date.\n   */\n  asOf?: string\n}\n\n/**\n * One reading in a series, for the components that draw change over time.\n *\n * `value` is `number | null` rather than `number` because a gap in a series is\n * information: a day with no reading is not a day with a reading of zero, and\n * charting it as zero invents a measurement. A `null` point is drawn as a break\n * in the line and described in words by the chart's text twin.\n *\n * `status` is optional and is an input, never a derivation. opsinjs does not\n * compare a point to a range and decide what it means, because it does not know\n * the reader; a point carries a verdict only when the consuming product attached\n * one.\n */\nexport interface TrendPoint {\n  /** When this reading was taken, ISO 8601. */\n  at: string\n  /** The reading, or `null` where there is no reading for this point. */\n  value: number | null\n  /** The verdict the product assigned to this point, if it assigned one. */\n  status?: ClinicalStatus\n}\n\n/**\n * How far a sheet is open.\n *\n * Three stops rather than a continuous height, because a sheet a reader can\n * leave at an arbitrary position is a sheet that will be left half over the\n * value it is explaining. `content` is as tall as what is inside it, `half` is\n * the resting stop that keeps the screen behind it readable, and `full` is the\n * whole surface.\n */\nexport type Detent = \"content\" | \"half\" | \"full\"\n\n/**\n * A rung of the material ladder — how a surface sits above what is behind it.\n *\n * These six names are the token names: every rung resolves a matching set of\n * `--opsin-material-<rung>-*` custom properties for blur, tint, shadow and\n * border. Where a specification page names a different set, the tokens win,\n * because the tokens are what actually renders.\n */\nexport type MaterialRung =\n  | \"canvas\"\n  | \"card\"\n  | \"raised\"\n  | \"sheet\"\n  | \"overlay\"\n  | \"scrim\"\n"

const SHARED_LIB_STATUS_TS = "/**\n * THE SINGLE STATUS VOCABULARY.\n *\n * `source.config.ts` declares the same two enums for frontmatter validation and\n * cannot export them — fumadocs-mdx refuses any export from a source config\n * that is not a collection — so this file is the runtime copy, and\n * `assert-ia.mts` asserts the two agree. If you add a status or a kind, add it\n * in both places in the same commit.\n *\n * Everything that renders a release phase, gates a section, or asks \"what\n * headings does this page need\" reads from here. Nothing re-declares it.\n *\n * This module has no imports, no JSX and no non-erasable TypeScript syntax,\n * because `scripts/*.mts` are executed by plain `node` and import it directly\n * with an explicit `.ts` extension.\n */\n\n/* ────────────────────────────────────────────────────────────────────────────\n   RELEASE PHASE\n   ──────────────────────────────────────────────────────────────────────────── */\n\nexport const STATUSES = [\n  \"stable\",\n  \"beta\",\n  \"alpha\",\n  \"planned\",\n  \"deprecated\",\n  \"considered\",\n] as const\n\n/** The release phase of a page or a catalogue entry. */\nexport type Status = (typeof STATUSES)[number]\n\nexport function isStatus(value: unknown): value is Status {\n  return (\n    typeof value === \"string\" && (STATUSES as readonly string[]).includes(value)\n  )\n}\n\nexport interface StatusMeta {\n  /** The word shown on the badge. */\n  label: string\n  /** One sentence a reader can act on, shown in the status legend and on hover. */\n  summary: string\n  /**\n   * What this phase PROMISES. Published verbatim on\n   * /docs/project/release-phases; the versioning policy is written against it.\n   */\n  promise: string\n  /** Sort order for the status matrix and the section-progress counts. */\n  order: number\n  /**\n   * Whether a page at this status may show a working example. Exactly one\n   * phase may not, and it is the one every page is currently at.\n   */\n  canDemonstrate: boolean\n  /** The clinical status level the docs chrome tints this badge with. */\n  tone: ClinicalStatus | \"unknown\"\n}\n\n/**\n * Ordered most-finished first. `order` is what `<StatusMatrix>` sorts on and\n * what `<SectionProgress>` counts in.\n */\nexport const STATUS_META: Record<Status, StatusMeta> = {\n  stable: {\n    label: \"Stable\",\n    summary: \"Finished. Safe to build on.\",\n    promise:\n      \"The JavaScript API, the rendered DOM, the data-* attributes and the CSS custom properties are all covered by semver. A breaking change requires a major version and a migration guide.\",\n    order: 0,\n    canDemonstrate: true,\n    tone: \"steady\",\n  },\n  beta: {\n    label: \"Beta\",\n    summary: \"Complete and in use, but the surface may still move.\",\n    promise:\n      \"Feature-complete and accessibility-reviewed. The API may change in a minor version with a deprecation notice and at least one release of overlap.\",\n    order: 1,\n    canDemonstrate: true,\n    tone: \"steady\",\n  },\n  alpha: {\n    label: \"Alpha\",\n    summary: \"Usable, incomplete, and expected to change.\",\n    promise:\n      \"It works and it is documented. The API may change in any release without a deprecation cycle. Not for a production health surface.\",\n    order: 2,\n    canDemonstrate: true,\n    tone: \"watch\",\n  },\n  planned: {\n    label: \"Planned\",\n    summary: \"Specified in full. Not implemented. There is no code.\",\n    promise:\n      \"The page you are reading is a specification: what it is for, when not to use it, what it asserts clinically, its proposed anatomy and API, and the accessibility bar the implementation must clear. Nothing has been built. Do not generate code against it.\",\n    order: 3,\n    canDemonstrate: false,\n    tone: \"attention\",\n  },\n  deprecated: {\n    label: \"Deprecated\",\n    summary: \"Still works. Being removed. A replacement is named.\",\n    promise:\n      \"It keeps working until the removal version stated on its page. Every deprecated entry names its replacement and its removal version; see /docs/project/deprecations.\",\n    order: 4,\n    canDemonstrate: true,\n    tone: \"watch\",\n  },\n  considered: {\n    label: \"Considered\",\n    summary:\n      \"Looked at, decided against for now, with the reason written down.\",\n    promise:\n      \"There is no page, no code and no plan. There IS a catalogue row saying why it is not here and what to reach for instead. A considered entry is a decision, not a backlog item.\",\n    order: 5,\n    canDemonstrate: false,\n    tone: \"unknown\",\n  },\n}\n\n/** Statuses in display order. */\nexport const STATUS_ORDER: Status[] = [...STATUSES].sort(\n  (a, b) => STATUS_META[a].order - STATUS_META[b].order\n)\n\n/** True when a page at this status must carry a not-implemented marker. */\nexport function isNotImplemented(status: Status): boolean {\n  return status === \"planned\" || status === \"considered\"\n}\n\n/* ────────────────────────────────────────────────────────────────────────────\n   PAGE KIND\n   ──────────────────────────────────────────────────────────────────────────── */\n\nexport const KINDS = [\n  \"component\",\n  \"foundation\",\n  \"health\",\n  \"accessibility\",\n  \"content\",\n  \"pattern\",\n  \"recipe\",\n  \"screen\",\n  \"handbook\",\n  \"reference\",\n  \"project\",\n  \"guide\",\n] as const\n\n/**\n * A page's kind. This is a contract, not a label: `kind` fully determines the\n * page's headings, and `assert-ia.mts` fails the build on a missing or an\n * unexpected one.\n */\nexport type Kind = (typeof KINDS)[number]\n\nexport function isKind(value: unknown): value is Kind {\n  return (\n    typeof value === \"string\" && (KINDS as readonly string[]).includes(value)\n  )\n}\n\n/* ────────────────────────────────────────────────────────────────────────────\n   THE CLINICAL AXES\n   ──────────────────────────────────────────────────────────────────────────── */\n\nexport const CLINICAL_STATUSES = [\n  \"steady\",\n  \"watch\",\n  \"attention\",\n  \"urgent\",\n] as const\n\n/**\n * What a reading means and what, if anything, to do about it.\n *\n * Four levels, ordered. This is the ONLY status vocabulary in the system: the\n * documentation chrome's callouts, the product's status pills and the dev\n * warnings all use these four words, so a developer reading a Callout in these\n * docs is reading the same vocabulary they will ship.\n *\n * A level is assigned by the consuming product from a reference range or a\n * threshold that the product owns. opsinjs never assigns one, because opsinjs\n * does not know the reader.\n */\nexport type ClinicalStatus = (typeof CLINICAL_STATUSES)[number]\n\n/**\n * The absence of an assertion — no reading, a stale reading, or a reading whose\n * reference range the product does not own.\n *\n * Deliberately NOT a fifth clinical status: rendering \"we do not know\" as a\n * status would claim a verdict the system does not have, and colouring it\n * anywhere near `watch` would let a reader read it as \"probably fine\".\n */\nexport type UnknownStatus = \"unknown\"\n\nexport type ClinicalStatusOrUnknown = ClinicalStatus | UnknownStatus\n\nexport interface ClinicalStatusMeta {\n  /** The word rendered beside the colour and the icon. Never omitted. */\n  word: string\n  /** The canonical example sentence, used by `<StatusLadder>`. */\n  sentence: string\n  /** Who is entitled to assign this level. */\n  assignedBy: string\n  /** The lucide icon name. Colour is never the only carrier of meaning. */\n  icon: string\n  /** 1 is the calmest. Used for ordering and for the escalation budget. */\n  level: number\n}\n\nexport const CLINICAL_STATUS_META: Record<\n  ClinicalStatusOrUnknown,\n  ClinicalStatusMeta\n> = {\n  steady: {\n    word: \"Steady\",\n    sentence: \"This reading is where it is expected to be.\",\n    assignedBy: \"The consuming product, from a reference range it owns.\",\n    icon: \"Check\",\n    level: 1,\n  },\n  watch: {\n    word: \"Watch\",\n    sentence: \"This reading is outside the usual range. Keep an eye on it.\",\n    assignedBy: \"The consuming product, from a reference range it owns.\",\n    icon: \"Eye\",\n    level: 2,\n  },\n  attention: {\n    word: \"Needs attention\",\n    sentence: \"This reading needs to be looked at. Contact your care team.\",\n    assignedBy: \"The consuming product, from a clinically reviewed threshold.\",\n    icon: \"TriangleAlert\",\n    level: 3,\n  },\n  urgent: {\n    word: \"Urgent\",\n    sentence: \"This reading needs help now.\",\n    assignedBy: \"A clinically reviewed threshold with a named clinical owner.\",\n    icon: \"OctagonAlert\",\n    level: 4,\n  },\n  unknown: {\n    word: \"Not known\",\n    sentence: \"We do not have a reading to show.\",\n    assignedBy: \"Nobody. This is the absence of an assertion.\",\n    icon: \"Minus\",\n    level: 0,\n  },\n}\n\nexport const HEALTH_CATEGORIES = [\n  \"sleep\",\n  \"heart\",\n  \"activity\",\n  \"nutrition\",\n  \"mind\",\n  \"labs\",\n] as const\n\n/**\n * What a reading is ABOUT. Identity, never verdict.\n *\n * A heart-red card does not mean something is wrong with a heart reading; it\n * means the reading concerns the heart. This is the axis products most often\n * misuse, because red already means something else everywhere else on the web.\n */\nexport type HealthCategory = (typeof HEALTH_CATEGORIES)[number]\n\nexport const HEALTH_CATEGORY_LABELS: Record<HealthCategory, string> = {\n  sleep: \"Sleep\",\n  heart: \"Heart\",\n  activity: \"Activity\",\n  nutrition: \"Nutrition\",\n  mind: \"Mind\",\n  labs: \"Labs\",\n}\n\nexport function isClinicalStatus(value: unknown): value is ClinicalStatus {\n  return (\n    typeof value === \"string\" &&\n    (CLINICAL_STATUSES as readonly string[]).includes(value)\n  )\n}\n\nexport function isHealthCategory(value: unknown): value is HealthCategory {\n  return (\n    typeof value === \"string\" &&\n    (HEALTH_CATEGORIES as readonly string[]).includes(value)\n  )\n}\n\nexport interface AxisConflict {\n  code: \"OPSIN-0001\"\n  category: HealthCategory\n  status: ClinicalStatus\n  message: string\n  docs: string\n}\n\n/**\n * THE NEVER-MIX RULE, as a function.\n *\n * Returns a conflict when a single surface has been given both a category and a\n * clinical status. `<StatusAxisDemo>` calls this and REFUSES to render the\n * mixed pair; the dev-mode warning OPSIN-0001 is the same check at runtime.\n *\n * Both axes may appear on one SCREEN — a heart-tinted card containing a\n * `watch` pill is correct and common. What may not happen is one surface\n * carrying both, because then the reader cannot tell which of the two the\n * colour is answering.\n */\nexport function axisConflict(input: {\n  category?: HealthCategory | null\n  status?: ClinicalStatus | null\n}): AxisConflict | null {\n  const { category, status } = input\n  if (!category || !status) return null\n  return {\n    code: \"OPSIN-0001\",\n    category,\n    status,\n    message:\n      \"This surface was given both a category (\" +\n      category +\n      \") and a clinical status (\" +\n      status +\n      \"). A surface carries one axis. Set the category on the surface and render the status as a StatusPill inside it.\",\n    docs: \"health/two-colour-axes\",\n  }\n}\n\n/* ────────────────────────────────────────────────────────────────────────────\n   SECTION CONTRACTS\n   ──────────────────────────────────────────────────────────────────────────── */\n\n/**\n * The H2s a page must have, by `kind`. This is the outline\n * `content/_templates/*.mdx` implements, `<PageTemplate>` asserts and\n * `assert-ia.mts` checks; all three read it from here so they cannot drift.\n *\n * `component` is absent on purpose: a component page's outline depends on its\n * status as well as its kind, and lives in COMPONENT_SECTIONS_BY_STATUS below.\n */\nexport const SECTION_OUTLINES: Record<Exclude<Kind, \"component\">, string[]> = {\n  foundation: [\n    \"Overview\",\n    \"How it works\",\n    \"Using it\",\n    \"Tokens\",\n    \"Accessibility impact\",\n    \"Related\",\n  ],\n  health: [\n    \"What this means\",\n    \"The rule\",\n    \"Why (evidence)\",\n    \"Applying it\",\n    \"Components that implement this\",\n    \"What this does not cover\",\n    \"Updates to this page\",\n  ],\n  accessibility: [\n    \"What we guarantee\",\n    \"What you own\",\n    \"How to check\",\n    \"Measured results\",\n    \"Known gaps\",\n    \"Updates to this page\",\n  ],\n  content: [\n    \"The rule\",\n    \"Approved / Rejected\",\n    \"Patterns\",\n    \"Banned words\",\n    \"Related components\",\n  ],\n  pattern: [\n    \"When to use\",\n    \"When not to use\",\n    \"How it works\",\n    \"Content\",\n    \"Accessibility\",\n    \"Research\",\n    \"Updates to this page\",\n  ],\n  recipe: [\n    \"The task\",\n    \"What you need\",\n    \"Build it\",\n    \"The copy\",\n    \"Get it right\",\n    \"Variations\",\n    \"Related\",\n  ],\n  screen: [\n    \"What this screen does\",\n    \"Composition\",\n    \"Preview\",\n    \"Safety notes\",\n    \"Accessibility\",\n    \"Status\",\n  ],\n  handbook: [\n    \"The short version\",\n    \"How it works\",\n    \"Do this\",\n    \"Not this\",\n    \"Gotchas\",\n    \"Related\",\n  ],\n  reference: [\"How this is generated\"],\n  project: [],\n  guide: [\"Overview\", \"Verify it worked\", \"Troubleshooting\", \"Next\"],\n}\n\n/**\n * `kind: project` is free-form and `kind: guide` has task sections between its\n * fixed first and last headings, so for these two the outline is a REQUIRED\n * SUBSET rather than the complete list. Everything else is exact.\n */\nexport const OUTLINE_IS_EXACT: Record<Exclude<Kind, \"component\">, boolean> = {\n  foundation: true,\n  health: true,\n  accessibility: true,\n  content: true,\n  pattern: true,\n  recipe: true,\n  screen: true,\n  handbook: true,\n  reference: false,\n  project: false,\n  guide: false,\n}\n\n/**\n * THE COMPONENT PAGE ANATOMY, status-gated.\n *\n * Sections 1 (header) and 22 (footer) are generated from frontmatter and never\n * appear as an H2, so they are not listed. Everything else is, in page order.\n *\n * At each status the listed sections are the WHOLE page. The others are\n * omitted, not left empty — a heading with nothing under it is worse than an\n * absent heading, and `<PageTemplate kind=\"component\">` fails the build either\n * way. `## Clinical meaning` is included here but is mandatory only for a\n * `health-*` category and forbidden outside one; `assert-ia.mts` checks both\n * directions, which is why it is listed separately below.\n */\nexport const COMPONENT_SECTIONS_BY_STATUS: Record<\n  Exclude<Status, \"considered\">,\n  string[]\n> = {\n  planned: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Proposed API\",\n    \"Content guidelines\",\n    \"Accessibility requirements\",\n    \"Related\",\n  ],\n  alpha: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Examples\",\n    \"Content guidelines\",\n    \"Accessibility\",\n    \"API reference\",\n    \"Related\",\n  ],\n  beta: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Examples\",\n    \"States\",\n    \"Content guidelines\",\n    \"Motion\",\n    \"Accessibility\",\n    \"Data attributes\",\n    \"CSS variables\",\n    \"Tokens\",\n    \"API reference\",\n    \"Cost\",\n    \"Related\",\n  ],\n  stable: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Examples\",\n    \"States\",\n    \"Content guidelines\",\n    \"Motion\",\n    \"Accessibility\",\n    \"Data attributes\",\n    \"CSS variables\",\n    \"Tokens\",\n    \"API reference\",\n    \"Cost\",\n    \"Related\",\n    \"Research and rationale\",\n  ],\n  deprecated: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Content guidelines\",\n    \"Accessibility\",\n    \"API reference\",\n    \"Related\",\n  ],\n}\n\n/**\n * Sections whose presence depends on the component's category rather than on\n * its status. Required when `category` starts with the prefix, and forbidden\n * when it does not.\n */\nexport const CATEGORY_GATED_SECTIONS: {\n  section: string\n  requiredForCategoryPrefix: string\n}[] = [{ section: \"Clinical meaning\", requiredForCategoryPrefix: \"health-\" }]\n\n/**\n * The H2 that carries a component's accessibility contract. It is named\n * \"Accessibility requirements\" at `planned`, because at that status it is a bar\n * the implementation must clear rather than a set of results, and\n * \"Accessibility\" from `alpha` onwards, when there is something to measure.\n * Mandatory at every status; never delegated upstream.\n */\nexport function accessibilitySectionFor(status: Status): string {\n  return status === \"planned\" ? \"Accessibility requirements\" : \"Accessibility\"\n}\n\n/** The sections required for a component page at a given status and category. */\nexport function componentSections(status: Status, category: string): string[] {\n  if (status === \"considered\") return []\n  const base = COMPONENT_SECTIONS_BY_STATUS[status]\n  return base.filter((section) => {\n    const gate = CATEGORY_GATED_SECTIONS.find((g) => g.section === section)\n    if (!gate) return true\n    return category.startsWith(gate.requiredForCategoryPrefix)\n  })\n}\n"

/**
 * The substrate appended to every component's `files`, named once and shared by
 * reference so that twenty-four components cost one copy of each file rather
 * than twenty-four. Nothing mutates these; the machine layer copies each entry
 * into a fresh object on the way out.
 *
 * These texts differ from the files on disk in exactly one way: a relative
 * import's `.ts` extension is dropped, because the repository needs it (plain
 * node resolves no extensions) and a consumer cannot compile with it (TS5097,
 * unless they enable `allowImportingTsExtensions`). See `forDistribution` in
 * scripts/build-registry.mts. A component's own text is never rewritten.
 */
const SHARED_FILES: RegistrySourceFile[] = [
  { path: "lib/opsinjs.ts", type: "registry:lib", target: "@lib/opsinjs.ts", content: SHARED_LIB_OPSINJS_TS },
  { path: "lib/status.ts", type: "registry:lib", target: "@lib/status.ts", content: SHARED_LIB_STATUS_TS },
]

